function getModeAnalyticsTranslation(key, lang) {
    return (modeanalyticsTranslations[lang] && modeanalyticsTranslations[lang][key]) ||
           (modeanalyticsTranslations.en && modeanalyticsTranslations.en[key]) || null;
}

function applyModeAnalyticsTranslations(lang) {
    let count = 0;
    document.querySelectorAll("[data-i18n]").forEach(el => {
        const key = el.getAttribute("data-i18n");
        if (key && (key.startsWith("review.mode-analytics.") || key.startsWith("review.common."))) {
            const translation = getModeAnalyticsTranslation(key, lang);
            if (translation) { el.textContent = translation; count++; }
        }
    });
    console.log(`Applied ${count} mode-analytics translations`);
}

window.addEventListener("languageChanged", e => setTimeout(() => applyModeAnalyticsTranslations(e.detail.language), 200));

if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => applyModeAnalyticsTranslations(window.i18n?.getCurrentLanguage() || "en"));
} else {
    applyModeAnalyticsTranslations(window.i18n?.getCurrentLanguage() || "en");
}
